definition.raw:
We define the group-lasso estimator by
\begin{align}\label{definition_hatmu}
(\hat\bmu,\hat\bfT) \in \arg\min_{\bm,\mathbf{T}}
\Big\{ \sum_{i=1}^n \| \bY_i -\bm - \boldsymbol{t}_i \|_2^2 + \sum_{i=1}^n \l_i \|\boldsymbol{t}_i\|_2 \Big\}.

theorem.raw:
\label{theorem_GSS}
\label{GSS}
Let $\d\in(0,1)$ be a prescribed tolerance level. The greedy subset selection estimator
with $\l = \nicefrac32\log(\nicefrac{2n}{\d})$ satisfies
\begin{equation}\label{GSS:1}
\sup_{\bfT\in \calM(p,n,s)}\prob_\bfT\Big(\|\hat\bL{}^{\rm GSS}
-\bL(\bfT)\|_2^2
    \le 60\sigma^2{s(p+\l s)}\Big) \ge 1-\d.
\end{equation}

\label{theorem_HT}
	Let $\hat{\bL}{}^{\rm GHT}$ be the estimator defined in~\eqref{definition_LHT} with the tuning parameter
	\begin{equation}
		\lambda^2/\sigma^2 = p+4\big\{\log(1+n/s^2)\vee p^{1/2}\log^{1/2}(1+n^2p/s^4)\big\}.
	\end{equation}
	There exists a universal constant $c>0$ such that, for every
	$\bfT\in\calM(p,n,s)$, it holds
	\begin{equation}
		\esp_\bfT\big[\big\| \hat{\bL}{}^{\rm GHT}-\bL(\bfT) \big\|_2^2\big] \le 
		c\sigma^2\Big(s^2p^{1/2}\log^{1/2}(1+n^2p/s^4)+s^2\log(1+n/s^2)+sp\Big).
	\end{equation}

\label{theorem_BT}
	Let $\hat{\bL}{}^{\rm HT}$ be the element-wise hard thresholding estimator
	defined by $\hat{\bL}{}^{\rm HT}_i = \sum_{j=1}^n \bY_{i,j} \fcar_{\bY_{i,j}>\lambda}$
	for $i\in [p]$. If the threshold $\l$  is chosen so that $\lambda^2=2\sigma^2\log(1+n/s^2)$, then
	\begin{equation}
		\sup_{\bfT\in\calM(p,n,s)}\esp_\bfT\big[\|\hat{\bL}{}^{\rm HT}-\bL(\bfT)\|^2 \big]
		\le c\sigma^2s^2p\log(1+n/s^2),
	\end{equation}
	where $c>0$ is a universal constant.

\label{theorem_ST}
	The estimator $\hat{\bL}{}^{\rm GST}=\bL(\hat{\bfT}^{\rm GST})$ defined
	in~\eqref{definition_STexplicite} with\footnote{Note that $\lambda_i=+\infty$
	if $\|\bY_i\|^2_2\le\sigma^2p$. This reflects
	the fact that there is no need to fit the signals of very low magnitude.}
	\begin{equation}
	\l_i = \frac{2\sigma\gamma\|\bY_i\|_2}{\big(\|\bY_i\|^2_2-\sigma^2p\big)_+^{1/2}}, \quad
	\gamma^2 = 
	4\big\{\log(1+n/s^2)\vee p^{1/2}\log^{1/2}(1+n^2p/s^4)
	\big\}
	\end{equation}
	satisfies, for every $\bfT\in\calM(p,n,s)$,
	\begin{equation}
	\esp_\bfT \big[\big\|\hat{\bL}{}^{\rm GST}-\bL(\bfT)\big\|^2 \big]
	\le c\sigma^2\Big(s^2p^{1/2}\log^{1/2}(1+n^2p/s^4)+s^2\log(1+n/s^2)+sp\Big),
	\end{equation}
	where $c>0$ is some universal constant.

\label{theorem_lowerbound}
	Assume that $1\le s\le n$, then there is a universal constant $c>0$ such that
	\begin{equation}
		\inf_{\hat{\bL}} \sup_{\bfT\in\calM(p,n,s)} \esp_\bfT \big\| \hat{\bL}-\bL(\bfT) \big\|^2 \ge c \Big[ \sigma^2 s^2 \log(1+n/s^2)+\sigma^2 sp \Big].
	\end{equation}

\label{theoreme_bornesuperieure1}
	Consider the estimators of $\bTheta$ and $\bmu$ defined in~\eqref{definition_hatmu} with $\lambda^2 = 32\sigma^2 p + 256\sigma^2 \log(n/\delta)$.
	Then, with probability at least $1-\d$ and provided that 
	$s\le n/32$, we have
	\begin{align}\label{theoreme_bornesuperieure1_1}
	\|\bTheta-\hat\bTheta\|_F^2 &\le 9 s\lambda^2,\quad 
	\|\bL_n(\hat\bTheta)-\bL_n(\bTheta)\|_2^2 \le \frac{288 s^2\lambda^2}{n^2}\\
	\|\hat\bmu-\bmu\|_2^2 &\le \frac{288 s^2\lambda^2}{n^2}+\frac{4\sigma^2 p}{n}
	+\frac{8\sigma^2\log(2/\delta)}{n}.
	\end{align}

lemma.raw:
\label{lemZ1}
In the event $\Omega_1\cap \Omega_2$, where
\begin{align}
\Omega_2 &= \Big\{\max_i\big|\|\bar\bxi_i\|_2^2-(1-\nicefrac1n)p\big|\le 0.5\gamma^2\Big\},
\end{align}
we have $w_i=0$ for every $i\not\in S$. Furthermore, under the condition
$\gamma^2 > 4\log(4n/\delta)+4 \{p\log(4n/\delta)\}^{1/2}$, the probability of
$\O_2$ is at least $1-\d/2$.

\label{lemZ2}
	There is a sequence of standard Gaussian random variables 
	$\eta_1,\ldots,\eta_n$ such that in the event $\O_1\cap\O_2$, it holds
	\begin{align}
	\|\bZ_i - \sigma\bar\bxi_i\|_2|w_i-1|
		\le 2\s|\eta_i| + \big\{|2\sigma\bar\bxi_i^\top\tilde\bDelta_n|\big\}^{1/2} + 
			1.96\sigma\gamma.
		\label{Z2}
	\end{align}

\label{lemme_Pi}
	Let us introduce the projection matrix $\bfPi = \bfI_n - \frac1n \bfJ_n$, where $\bfI_n$ and $\bfJ_n$ are respectively the $n\times n$ identity matrix and
    the constant matrix with all the entries equal to $1$.
    Let $\bfU$ be a $p\times n$ matrix with columns $\bu_i\in\RR^p$ satisfying, for some set $S\subset \{1,\ldots,n\}$ and some real number $a>0$,
	\begin{equation}\label{cone_cond}
		\sum_{i\not\in S} \|\bu_i\|_2 \le a \sum_{i\in S} \|\bu_i\|_2,
	\end{equation}
	then
	\begin{equation}
		\|\bfU\bfPi\|_F^2 \ge \Big( 1 - \frac{(1+a)^2|S|}{n} \Big) \|\bfU\|_F^2.
	\end{equation}

\label{lemme_chideux}
	If $\eta$ is a random variable drawn from the $\chi^2_d$ distribution, then for every $x>0$
	\begin{equation}
		\prob\big(\eta \ge d+ x\big) \le e^{-\frac1{16d} x (x\wedge 4d)} .
	\end{equation}

\label{lemme_esperancechideux}
	If $\eta$ is a random variable drawn from the $\chi^2_d$ distribution, then for every $x>0$ and $d\ge 2$,
	\begin{equation}
	\esp\big(\eta \fcar_{\eta\ge d+x}\big) \le 2d\,e^{-x^2/32d} \,\fcar_{x< 4d} +
	2xe^{-x/4} \fcar_{x\ge 4d}.
	\end{equation}

\label{lemme_probabiliteA}
	Denote $\bfPi=I_n-\frac1n \bfJ_n$  where $\bfI_n$ is the identity matrix in dimension $n$ and $\bfJ_n$ is the constant matrix with only $1$ coefficients, and assume that
	\begin{equation}
		\bxi_1,\ldots,\bxi_n \simiid \mathcal{N}(0,\bfI_p).
	\end{equation}
	Then, with probability at least $1-\d$, the matrix $\bXi = [\bxi_1,\ldots,\bxi_n]$ 
	satisfies
	\begin{equation}
		\max_{i=1,\ldots,n}  \big\|(\bXi\bfPi)_i\big\|_2^2 \le 2p+16\log(n/\delta).
	\end{equation}

\label{lemma_Wishart1}
	Assume that $\bfA$ is a $N\times n$ random matrix with independent standard Gaussian entries.
	Then, for any $t\ge 0$,  with probability at least $1-2e^{-t^2/2}$, it holds that
	\begin{equation}
	\|\bfA\| \le \sqrt{N}+\sqrt{n}+t.
	\end{equation}

proposition.raw:
\label{theorem_HT_lowerbound}
Let us denote by $\hat{\bL}{}^{\rm GHT}_\l$ the estimator defined in~\eqref{definition_LHT} with a threshold $\l>0$. There are two universal constants $p_0\in\NN$ and $c>0$, such that for any $p\ge p_0$ and $s\le n/61$, the following lower bound holds
	\begin{equation}
		\inf_{\l>0}\sup_{\bfT\in\calM(p,n,s)} \esp_\bfT \big\| \hat{\bL}{}^{\rm GHT}_\l-\bL(\bfT) \big\|_2^2 \ge c\sigma^2\Big((s^2p^{1/2})\wedge (np)+s^2\log(1+n/s^2)+sp\Big).
	\end{equation}

Assume that $s\in[n]$, then there is a universal constant $c>0$ such that
	\begin{equation}
		\inf_{\hat{\bL}} \sup_{\bfT\in\calM(1,n,s)} \esp_\bfT \big( \hat{\bL}-\bL(\bfT) \big)^2 \ge c \sigma^2 s^2 \log(1+n/s^2).
	\end{equation}

The problem of estimating the linear functional $\bL_n(\bTheta) = (\nicefrac1n)\sum_{i\in[n]}
\bt_i$ in model \eqref{definition_observation1} is not easier, in the minimax sense, than that of estimating $\bmu$. More precisely, we have
\begin{align}
\frac{\sigma^2 p}{n}\le \inf_{\hat\bmu}\sup_{\bmu,\bTheta} \esp[\|\hat\bmu-\bmu\|_2^2]\le
2\inf_{\hat\bL_n}\sup_{\bTheta} \esp[\|\hat\bL_n-\bL_n(\bTheta)\|_2^2]
+\frac{2\sigma^2 p}{n},
\end{align}
where the sup in the left-hand side and in the right-hand side are taken,
respectively, over all $\bTheta\in\calM(p,n,s)$ and over all $(\bmu,\bTheta)\in
\RR^p\times\calM(p,n,s)$.

Let $\hat\bmu:\RR^{p\times n}\to\RR^p$ be an estimator of $\bmu$ that can be applied
both to the data matrix $\bfX = [\bX_1,\ldots,\bX_n]$ from Huber's model and to $\bfY$ 
from our model \eqref{definition_observation}. Then, we have
\begin{align}
\underbrace{\sup_{\bfQ}\esp_{\bmu,\bfQ}[\|\hat\bmu(\bfX)-\bmu\|_2^2]}
_{\text{\rm risk in the Huber model}}\le
\esp_{\hat s\sim \mathcal B(n,s/n)}
\bigg[\underbrace{\sup_{\bTheta\in\calM(n,p,\hat s)}
\esp_{\bmu,\bTheta}\big[\|\hat\bmu(\bfY)-\bmu\|_2^2\big]
}_{\text{\rm risk in our model \eqref{definition_observation}}}\bigg].
\end{align}
The supremum of the left-hand side is over all probability distributions $\bfQ$ on $\RR^p$
such that\footnote{We denote by $*$ the convolution of the distributions.} 
$\bfQ = \bfQ_0 * \mathcal N_p(\mathbf 0, \sigma^2\bfI_p)$, 
while the notation $\mathcal B(n,s/n)$ stands for the binomial distribution.

\label{theoreme_bornesuperieure2}
	Let us set $\bZ_i = (\bfY\bfPi)_i+\tilde\bL_n$, where $\tilde\bL_n$ is a
	preliminary estimator of $\bL_n(\bTheta)$. Let $\d\in(0,1)$ be a tolerance level.
	Consider the estimator of $\bfT$ defined by concatenating the vectors
	\begin{align}\label{Z0}
	\hat\bt_i = \bZ_i \bigg(1-\frac{\sigma\gamma}{(\|\bZ_i\|_2^2-\frac{n-1}{n}
	\sigma^2 p)_+^{1/2}}\bigg)_+,
	\end{align}
	where $\gamma^2 > 4\log(4n/\delta)+4 \{p\log(4n/\delta)\}^{1/2}$ is a tuning parameter.
	Define the event
	\begin{align}
	\Omega_1 &= \Bigg\{\|\tilde\bL_n-\bL_n(\bTheta)\|_2	< 
	\frac{\sigma\gamma^2}{4\sqrt{p+\gamma^2}}\Bigg\}.
	\end{align}
	There is an event $\bar\O$ (the same for all estimators $\tilde\bL_n$) of probability 
	at least $1-\d$, such that on $\O_1\cap\bar\O$, we have
	\begin{align}
		\|\bL(\hat{\bTheta}-\bTheta) \|_2
		\le 4\sigma\Big(\,s\gamma+ s + \sqrt{sp} +  \{2s\log(4/\delta)\}^{1/2}\Big).
			\label{Z6}
	\end{align}

proof.raw:
Using the triangle inequality several times, we get
\begin{align}
\|\hat\bL{}^{\rm GSS}-\bL(\bfT)\|_2
    &\le \|\bL(\bfY_{\hat S})-\bL(\bfY_{S})\|_2+ \|\bL(\bfY_{S})- \bL(\bfT_S)\|_2\\
    &\le \|\bL(\bfY_{\hat S\setminus S})\|_2+\|\bL(\bfY_{S\setminus \hat S})\|_2
			+ \sigma\|\bL(\bxi_{S})\|_2 \phantom{\Big(}\\
    &\le \sigma\|\bL(\bxi_{\hat S\setminus S})\|_2+\|\bL(\bfY_{S\setminus \hat S})\|_2
			+ \sigma\|\bL(\bxi_{S})\|_2.
    \label{line:3}
\end{align}
To upper bound the three terms of the right hand side, we introduce the event
\begin{equation}
\Omega_\l = \Big\{\|\bL(\bxi_J) \|_2^2\le 2|J|(p+\l |J|)\text{ for all }
J\subseteq [n]\Big\}.
\end{equation}
We will show that the following three claims are true for the tuning parameter $\l$ chosen as in the statement of the theorem.
\begin{description}\itemsep=5pt
\item[Claim 1:] On the event $\Omega_\l$, at least half of the elements of each $\hat J_\ell$
belong to the true sparsity pattern $S$. Thus $|\hat S|\le 2s$.
\item[Claim 2:] $\|\bL(\bfY_{S\setminus\hat S})\|_2^2\le 12\sigma^2 s(p+\l s)$.
\item[Claim 3:] The probability of $\Omega_\l$ is close to $1$.
\end{description}
Let us first show that these claims imply the claim of the theorem. Indeed,  the second term of the right hand side of \eqref{line:3} is bounded by $\sigma\sqrt{12s(p+\l s)}$ in view of Claim 2. The third term is bounded by $\sigma\sqrt{2s(p+\l s)}$ on the event $\O_\l$. Concerning the first term, we know that on $\O_\l$ it is bounded by $\sigma\sqrt{2|\hat S|(p+\l |\hat S|)}$. In view of Claim 1, $|\hat S|\le 2s$. All these inequalities imply that
\begin{align}
\|\hat\bL{}^{\rm GSS}-\bL(\bfT)\|_2^2
    &\le 60\sigma^2{s(p+\l s)}
\end{align}
on the event $\O_\l$. This is exactly the claim of the theorem.

Let us prove now Claims 1-3. To prove the first claim, let us assume that there is a set $J$ among $\hat J_1,\ldots,\hat J_\ell$ and a subset $J_0\subset J$ of cardinality\footnote{To avoid uninteresting and irrelevant technicalities, we assume here that $|J|$ is even.} $|J|/2$ such that $J_0\subset S^c$. This readily implies that $\|\bL(\bfY_{J})\|_2^2\ge 12\sigma^2 |J|(p+\l |J|)$ and $\|\bL(\bfY_{J\setminus J_0})\|_2^2< 6\sigma^2 |J|(p+\l |J|/2)$. Using the additivity of $\bL$ and the triangle inequality, we get
\begin{align}
\|\bL(\bfY_{J})\|_2^2
    & \le (\|\bL(\bfY_{J\setminus J_0})\|_2+ \sigma\|\bL(\bxi_{J_0})\|_2)^2 \phantom{\frac32} \\
    & \le \frac32\|\bL(\bfY_{J\setminus J_0})\|_2^2+ 3\sigma^2\|\bL(\bxi_{J_0})\|_2^2\\
    & < 9\sigma^2 |J|(p+\l |J|/2)+ 3\sigma^2 |J|(p+\l|J|/2) \phantom{\frac32}\\
    & < 12\sigma^2 |J|(p+\l|J|). \phantom{\frac32}
\end{align}
This is in contradiction with the fact that $J$ is one of the sets $\hat J_1,\ldots,\hat J_L$. So, Claim 1 is proved.

The proof of Claim 2 is simpler. By construction, the set $S\setminus \hat S$ is a subset of $I_L$, where $L$ is the number of steps performed by the algorithm. Since the algorithm terminated after the $L$th step, this means that $\calI$ was empty, which implies  that $\|\bL(\bfY_{S\setminus\hat S})\|_2^2\le 12\sigma^2 |S\setminus\hat S|(p+\l|S\setminus\hat S|) \le 12\sigma^2 s(p+\l s)$.

It remains to prove Claim 3. This can be done using the union bound and tail bounds for $\chi^2_p$-distributed random variables. Indeed, we have
\begin{align}
\prob_\bfT\big(\Omega_\lambda^c\big)
    &\le \sum_{k=1}^n \prob_\bfT\big(\exists J\subset [n]\text{ s.t. } |J|=k\text{ and }
            \|\bL(\bxi_J)\|_2^2> 2|J|(p+\l|J|)\big)\\
    &\le \sum_{k=1}^n {{n}\choose{k}} \max_{J:|J|=k}
            \prob_\bfT\big(\|\bL(\bxi_J)\|_2^2> 2k(p+\l k)\big)\\
    &\le \sum_{k=1}^n {{n}\choose{k}}
            \prob\big(\eta > 2p + 2 \l k\big)
\end{align}
where $\eta\sim \chi^2_p$. Using the well known bound on the tails of the $\chi^2_p$
distribution, we get
\begin{align}
\prob\big(\Omega_\lambda^c\big)
    &\le \sum_{k=1}^n {{n}\choose{k}} e^{-2\l k/3} = (1+e^{-2\l/3})^n-1.
\end{align}
Therefore, for $\lambda = \nicefrac32\log(\nicefrac{2n}{\delta})$, we obtain that  $\prob_\bfT\big(\Omega_\lambda^c\big)\le \delta$. This completes the proof of Claim~3 and of the theorem.

Recall that $\bXi =(\bxi_1, \ldots,\bxi_n)$. First, we decompose
	\begin{align}
		\hat{\bL}{}^{\rm GHT}-\bL(\bfT)
		&= \bL(\bY_S-\bTheta) - \bL(\bY_{S\setminus S_\lambda} )+ \bL(\bY_{S_\l\setminus S})\\
		&= \sigma\bL(\bXi_S) - \bL(\bY_{S\setminus S_\lambda} )+ \sigma\bL(\bXi_{S_\l\setminus S})\\
		&= \sigma\bL(\bXi_{S\cap S_\lambda}) - \bL(\bTheta_{S\setminus S_\lambda} )+ \sigma\bL(\bXi_{S_\l\setminus S}).
		\label{decomposition}
	\end{align}
	so that
	\begin{align}\label{ineq:2}
	\big\| \hat{\bL}{}^{\rm GHT}-\bL(\bfT) \big\|_2 &\le \sigma\|\bL(\bXi_{S\cap S_\lambda})\|_2 +
	\|\bL(\bTheta_{S\setminus S_\lambda})\|_2 + \sigma\|\bL(\bXi_{S_\l \setminus S})\|_2.
	\end{align}
	The first term corresponds to the stochastic error of estimating the signal vectors   
	that are correctly identified as nonzero. We can write
	\begin{equation}
	\|\bL(\bXi_{S\cap S_\lambda})\|_2 = \|\bXi_{S}\mathbf 1_{S\cap S_\lambda}\|_2\le
 	\sqrt{s}\|\bXi_{S}\|.
	\end{equation}
	The second-order moment of the spectral norm of the random matrix $\bXi_S$ can be
	evaluated using well-known upper bounds on the spectral norm of matrices with
	independent Gaussian entries, recalled in \Cref{lemma_Wishart2} below, so that
	\begin{equation}\label{esperance_norm}
	\esp_\bfT \big[\|\bL(\bXi_{S\cap S_\lambda})\|_2^2\big] \le 3s^2 + 3sp+12s.
	\end{equation}
 	Set $\eta_i=\btheta_i^\top\bxi_i/\|\btheta_i\|_2$. We can control the second term in \eqref{ineq:2} using the following inequality
    \begin{align}
	\|\bL(\bTheta_{S\setminus S_\lambda})\|_2&\le \sum_{i\in S} \|\bt_i\|_2 \fcar_{\|\bt_i\|^2<\lambda^2	-2\sigma\bt_i^\top \bxi_i-\sigma^2\|\bxi_i\|^2} \\
	&\le s(\lambda^2-\sigma^2p)^{1/2}+2\sigma\sum_{i\in S} |\eta_i| + \sigma\sum_{i\in S} \big| \|\bxi_i\|^2-p\, \big|^{1/2}.
	\end{align}
	This readily yields
	\begin{equation}\label{eval_on_support}
	\esp_\bfT \big[\|\bL(\bTheta_{S\setminus S_\lambda})\|_2^2]^{1/2}
	\le s(\lambda^2-\sigma^2p)^{1/2}+2\sigma s + \sigma s (2p)^{1/4}.
	\end{equation}
	The third term in \eqref{ineq:2}
	corresponds to the Type II error in the problem of support estimation. Denoting
	$t=(\lambda^2-\sigma^2p)/\sigma^2$, and using tail bounds for the chi-squared
	random variables (see \Cref{lemme_esperancechideux} below), we get
	\begin{align}
	\esp_\bfT[\|\bXi_{S_\l \setminus S}\|_2^2]
	    &= \esp_\bfT\bigg[\bigg\| \sum_{i\in S^c} \bxi_i\fcar(\|\bxi_i\|_2\ge \l/\s)\bigg\|_2^2\bigg]\\
	    &= \sum_{i\in S^c}\esp_\bfT[\|\bxi_i\|_2^2\fcar(\|\bxi_i\|_2^2\ge p+t)]\\
	    &\le 	2n \big( pe^{-t^2/32p}\,\fcar_{t< 4p} + t
	    e^{-t/4}\fcar_{t \ge 4p}\big).
	\end{align}
	Using the fact that $t= 4\log(1+n/s^2)\vee\big\{16p\log(1+n^2p/s^4)\big\}^{1/2}$
	we arrive at
	\begin{align}
	\esp_\bfT[\|\bXi_{S_\l \setminus S}\|_2^2]
	    &\le 	\Big(8s^2\log(1+n/s^2)\Big)\vee \Big(2s^2\sqrt{p}
			\wedge 2np\Big).
	\end{align}
	The result follows from the previous upper bounds and the choice of $\l$.

To ease notation, for every random vector
$X$ we write $\|X\|_{L_2}$ for $(\esp[\|X\|_2^2])^{1/2}$. We first notice that
	\begin{align}
	\hat{\bL}{}^{\rm GST}-\bL(\bTheta) &=  \sum_{i\in S} \bt_i \bigg\{\bigg(1-\frac{\sigma\gamma}
	{(\|\bY_i\|^2_2-\sigma^2p)_+^{1/2}}\bigg)_+-1\bigg\} \qquad &(:=T_1)\\
	&+ \sigma\sum_{i\in S} \bxi_i \bigg(1-\frac{\sigma\gamma}{\big(\|\bY_i\|^2_2-\sigma^2p\big)_+^{1/2}}\bigg)_+ \qquad &(:=T_2)\\
	&+ \sigma\sum_{i\not\in S} \bxi_i \bigg(1-\frac{\sigma\gamma}{\sigma\big(\|\bxi_i\|^2_2-p\big)_+^{1/2}}\bigg)_+\qquad &(:=T_3),
	\end{align}	
	so that we only need to bound the expected squared norms of the three terms in the right-hand side. These three terms have the following meanings: the first one is the bias of estimation
or the approximation error, the second term is the stochastic error on the support $S$,
whereas the third term is the stochastic error on $S^\complement$.

\paragraph{Evaluation of the approximation error}
For the first term, we use the Minkowski inequality as follows
	\begin{align}\label{eqT1}
	\|T_1\|_{L_2}\le \Big\|\sum_{i\in S} \bt_i \fcar_{\|\bY_i\|_2^2\le\sigma^2 (p+\gamma^2)
	}\Big\|_{L_2} + \sigma\Big\|\sum_{i\in S}  \bt_i \frac{\gamma\,\fcar_{\|\bY_i\|_2^2>\sigma^2 
	(p+\gamma^2)}}{\big(\|\bY_i\|^2_2-\sigma^2p\big)^{1/2}}\Big\|_{L_2}.
	\end{align}
	The first part can be treated exactly as in \eqref{eval_on_support} of the proof 
	of~\Cref{theorem_HT}, \ie
	\begin{equation}\label{eqT1a}
		\Big\|\sum_{i\in S} \bt_i \fcar_{\|\bY_i\|_2^2\le\sigma^2 (p+\gamma^2)
	}\Big\|_{L_2} \le \sigma s \big(\gamma+2 +  (2p)^{1/4}\big).
	\end{equation}
	For assessing the second term in the right hand side of \eqref{eqT1}, 
	we set 
	\begin{align}
	T_{1,i} = \frac{\|\bt_i\|_2\gamma\,\fcar_{\|\bY_i\|_2^2>\sigma^2 (p+\gamma^2)}}
	{(\|\bt_i\|^2_2+2\sigma\bt_i^\top\bxi_i+\sigma^2\big(\|\bxi_i\|_2^2-p\big))^{1/2}} .
	\end{align}
	We consider two cases. The first case corresponds to 
	$\big|2\sigma\bt_i^\top\bxi_i+\sigma^2\big(\|\bxi_i\|_2^2-p\big)\big|<\|\bt_i\|_2^2/2$. 
	In this case one easily checks that  $T_{1,i}\le \sqrt{2}\,\gamma$. In the second case, 
	$\big|2\sigma\bt_i^\top\bxi_i+\sigma^2\big(\|\bxi_i\|_2^2-p\big)\big|\ge\|\bt_i\|_2^2/2$, 
	we have 
	\begin{equation}
		\|\bt_i\|_2^2/4 \le 2\s|\bt_i^\top\bxi_i| \quad \text{or} \quad \|\bt_i\|_2^2/4 \le 
		\sigma^2\big|\|\bxi_i\|_2^2-p\big|.
	\end{equation}
	This readily implies that 
	\begin{equation}
		T_{1,i}= \frac{\|\bt_i\|\gamma\,\fcar_{\|\bY_i\|_2^2>\sigma^2 (p+\gamma^2)}}
	  {\big(\|\bY_i\|^2_2-\sigma^2p\big)^{1/2}}\le \|\bt_i\| \le 8\sigma 
		\frac{|\bt_i^\top\bxi_i|}{\|\bt_i\|_2}+ 2\sigma\sqrt{|\|\bxi_i\|_2^2-p|}.
	\end{equation}
	Therefore, using the fact that $\esp[|\bt_i^\top\bxi_i|^2] = \|\bt_i\|_2^2$ 
	and $\esp[|\|\bxi_i\|_2^2-p|^2] = 2p$, we get	
	\begin{equation}
		\|T_{1,i}\|_{L_2} \le 8\sigma + 2\sigma (2p)^{1/4}.
	\end{equation}
	Combining this inequality with \eqref{eqT1} and \eqref{eqT1a}, we arrive at
	\begin{align}
		\|T_1\|_{L_2} &\le \sigma 
		s\gamma+2\sigma s + \sigma s(2p)^{1/4} + 8\sigma s+ 2\sigma s(2p)^{1/4}\\
		&= \sigma s\gamma+10\sigma s + 3\sigma s(2p)^{1/4}.\label{eqT1c}
	\end{align}

	\paragraph{Evaluation of the stochastic error on $S$} 
	The second term can be treated
	exactly as in the proof of Theorem~\ref{theorem_HT} using Wishart matrices, \ie
	\begin{equation}
	\|T_2\|_{L_2}^2 \le \sigma^2 s\esp[\|\bXi_S\|^2] \le \sigma^2(3s^2+3sp+12s).
	\end{equation}

	\paragraph{Evaluation of the stochastic error on $S^\complement$} For the third term,
	we write
	\begin{align}
		\|T_3\|_{L_2}^2=\sigma^2\bigg\| \sum_{i\not\in S} \bxi_i
		\bigg(1-\frac{\gamma}{\big(\|\bxi_i\|^2_2-p\big)_+^{1/2}}\bigg)_+\bigg\|_{L_2}^2
			&= \sigma^2\sum_{i\not\in S} \bigg\|\bxi_i\bigg(1-\frac{\gamma}{(\|\bxi_i\|^2_2
				-p)_+^{1/2}}\bigg)_+\bigg\|_{L_2}^2\\
			&\le \sigma^2\sum_{i\not\in S} \esp\big[\|\bxi_i\|_2^2 \fcar_{\|\bxi_i\|_2^2> p+
			\gamma^2}\big].
	\end{align}
  We conclude by~\Cref{lemme_esperancechideux} that the last term satisfies
	\begin{equation}
		\|T_3\|_{L_2}^2\le 
		2n\sigma^2  \big( pe^{-\gamma^4/32p}\,\fcar_{\gamma^2< 4p} +
		\gamma^2e^{-\gamma^2/4}\fcar_{\gamma^2\ge 4p}\big).
	\end{equation}
	Using the fact that $\gamma^2= 4\log(1+n/s^2)\vee\big\{16p\log(1+n^2p/s^4)
	\big\}^{1/2}$ we arrive at
	\begin{align}
	\|T_3\|_{L_2}^2
	    &\le \sigma^2	\Big(8s^2\log(1+n/s^2)\Big)\vee \Big(2s^2\sqrt{p}
			\wedge 2np\Big).
	\end{align}
This completes the proof of the theorem.

In view of~\eqref{definition_groupestimator}, we have
	\begin{equation}
	\big\| (\bTheta-\hat{\bTheta})\bfPi + \sigma\bXi\bfPi \big\|_F^2 + \l \sum_{i=1}^n \|\hat\bt_i\|_2 \le \sigma^2 \| \bXi\bfPi \|_F^2 + \l \sum_{i=1}^n \|\bt_i\|_2.
	\end{equation}
	Developing the left-hand side, this yields
	\begin{align}
	\| (\bTheta-\hat{\bTheta})\bfPi \|_F^2 &\le 2\sigma\sum_{n=1}^n 
	(\bXi\bfPi)_i^\top(\hat\bt_i-\bt_i) + \l \sum_{i=1}^n \big\{ \|\bt_i\|_2 - 
	\|\hat\bt_i\|_2\big\}.
	\end{align}
	Using the Cauchy-Schwarz inequality, we have on the event
	\begin{equation}\label{definition_evenementA}
	\mathcal{A} = \Big\{ \max_{i\in [n]} \big\| (\bXi\bfPi)_i \big\|_2 \le \frac{\lambda}{4\sigma} \Big\}
	\end{equation}
	that
	\begin{align}
	\|(\bTheta-\hat{\bTheta})\bfPi\|_F^2
	&\le \frac\l2 \sum_{i=1}^n \Big\{ \|\hat\bt_i-\bt_i\|_2
			+ 2 \|\bt_i\|_2 - 2 \|\hat\bt_i\|_2 \Big\} \\
	&\le \frac{3\lambda}2 \sum_{i\in S} \|\hat\bt_i-\bt_i\|_2 -
			\frac\l2 \sum_{i\not\in S} \|\hat\bt_i-\bt_i\|_2,
	\end{align}
	where we used the triangular inequality. The last inequality implies that
	\begin{align}\label{theoreme_bornesuperieure1_2}
	\sum_{i\not\in S} \|\hat\bt_i-\bt_i\|_2\le 3\sum_{i\in S} \|\hat\bt_i-\bt_i\|_2.
	\end{align}
	Furthermore, using the Cauchy-Schwarz inequality, we get
	\begin{equation}
	\|(\bTheta-\hat\bTheta)\bfPi\|_F^2 \le \frac{3\lambda}2 \sqrt{s} \|\bTheta-\hat\bTheta\|_F.
	\end{equation}
	We can then apply Lemma~\ref{lemme_Pi}, since~(\ref{theoreme_bornesuperieure1_2}) 
	ensures that the condition is satisfied with $a=3$: provided that $s\le n/16$, we have
	\begin{equation}
	\frac12 \|\hat\bTheta-\bTheta\|_F^2 \le \frac{3\lambda}2 \sqrt{s} \|\hat\bTheta-\bTheta\|_F,
	\end{equation}
	so that
	\begin{equation}
	\|\hat\bTheta-\bTheta\|_F \le 3 \l \sqrt{s}.
	\end{equation}
	The first claim follows now from~\Cref{lemme_probabiliteA}. To show the second inequality,
	it suffices to remark that
	\begin{align}
	\|\hat\bmu-\bmu\|_2^2
			& \le \frac2{n^2}\|(\hat\bTheta-\bTheta)\mathbf 1_n\|_2^2 +2\sigma^2\|\bL_n(\bXi)\|_2^2\\
			& \le \frac{2}{n^2}\bigg(\sum_{i\in [n]}\|\hat\btheta_i-\btheta_i\|_2\bigg)^2 
				+2\sigma^2\|\bL_n(\bXi)\|_2^2\\
			& \le \frac{2}{n^2}\bigg(4\sum_{i\in S}\|\hat\btheta_i-\btheta_i\|_2\bigg)^2 
				+2\sigma^2\|\bL_n(\bXi)\|_2^2\\
			& \le \frac{32s}{n^2}\sum_{i\in S}\|\hat\btheta_i-\btheta_i\|_2^2 
				+2\sigma^2\|\bL_n(\bXi)\|_2^2\\				
			& \le \frac{288s^2\lambda^2}{n^2}
				+2\sigma^2\|\bL_n(\bXi)\|_2^2.								
	\end{align}
To complete the proof, we use the fact that $n\|\bL_n(\bXi)\|_2^2$ is a $\chi^2(p)$
random variable, which implies that with probability at least $1-\d/2$ it is bounded
from above by $2p+4\log(2/\delta)$.

To ease notation, we set $\sigma_{n,p}^2 = (n-1)\sigma^2p/n$, 
$w_i=\big( 1-\sigma\gamma/\sqrt{(\|\bZ_i \|_2^2-\sigma_{n,p}^2)_+} \big)_+$,
$\tilde\bDelta_n = \tilde\bL_n-\bL_n(\bTheta)$ and $\bar\bxi_i= \bxi_i-\bar\bxi$.
Then,
	\begin{equation}
		\bZ_i = \bt_i + \tilde\bDelta_n + \sigma\bar\bxi_i.
	\end{equation}	
We first show that with high probability the weights $w_i$
vanish outside the support $S$.

\begin{lemma}\label{lemZ1}
In the event $\Omega_1\cap \Omega_2$, where
\begin{align}
\Omega_2 &= \Big\{\max_i\big|\|\bar\bxi_i\|_2^2-(1-\nicefrac1n)p\big|\le 0.5\gamma^2\Big\},
\end{align}
we have $w_i=0$ for every $i\not\in S$. Furthermore, under the condition
$\gamma^2 > 4\log(4n/\delta)+4 \{p\log(4n/\delta)\}^{1/2}$, the probability of
$\O_2$ is at least $1-\d/2$.
\end{lemma}

	Using equation~\eqref{Z0} and the fact that $w_i=0$ for every
	$i\not\in S$ in the event $\Omega_1\cap\Omega_2$, we get	
	\begin{align}
	\bL(\hat{\bTheta}-\bTheta)
		&= \sum_{i=1}^n \bZ_i w_i-\sum_{i\in S} \bt_i
		= \sum_{i\in S} \big(\bZ_i w_i -\bt_i\big).
	\end{align}
	Replacing $\bZ_i$ by $\bt_i + \tilde\bDelta_n + \sigma\bar\bxi_i$ and using the
	triangle inequality, we obtain
	\begin{align}
	\|\bL(\hat{\bTheta}-\bTheta) \|_2
		&\le \Big\|\sum_{i\in S} \big(\bZ_i-\sigma\bar\bxi_i\big) (w_i-1)\Big\|_2 +
			\Big\|\sum_{i\in S} \big(\bZ_i-\bt_i\big)+\sigma\bar\bxi_i(w_i-1)\Big\|_2\\
		&\le \sum_{i\in S} \|\bZ_i-\sigma\bar\bxi_i\|_2 |w_i-1| +
			\Big\|\sum_{i\in S} \big(\tilde\bDelta_n
			+ \sigma\bar\bxi_i w_i\big)\Big\|_2\\
		&\le \sum_{i\in S} \|\bZ_i-\sigma\bar\bxi_i\|_2 |w_i-1| +
			{s}\big\|\tilde\bDelta_n\big\|_2
			+ \sigma\Big\|\sum_{i\in S}\bar\bxi_i w_i\Big\|_2.\label{Z1}
	\end{align}	
	We will now evaluate the first and the third terms of the right-hand side.	
	\begin{lemma}\label{lemZ2}
	There is a sequence of standard Gaussian random variables 
	$\eta_1,\ldots,\eta_n$ such that in the event $\O_1\cap\O_2$, it holds
	\begin{align}
	\|\bZ_i - \sigma\bar\bxi_i\|_2|w_i-1|
		\le 2\s|\eta_i| + \big\{|2\sigma\bar\bxi_i^\top\tilde\bDelta_n|\big\}^{1/2} + 
			1.96\sigma\gamma.
		\label{Z2}
	\end{align}
	\end{lemma}

	Let us introduce the $p\times s$ matrix $\bXi_S = [\,\bar\bxi_i; i\in S\,]$ (the matrix
	obtained by concatenating the vectors $\bar\bxi_i$ with subscript $i$ running over $S$).
	Using the H\"older inequality, one can check that
	\begin{align}
	\sum_{i\in S}\big\{2\s|\bar\bxi_i^\top\tilde\bDelta_n|\big\}^{1/2}
			&\le \sqrt{2\sigma}\, s^{3/4} \bigg(\sum_{i\in S} |\bar\bxi_i^\top\tilde\bDelta_n|^2
				\bigg)^{1/4}\\
			&= \sqrt{2\sigma}\, s^{3/4} \|\bXi_S^\top\tilde\bDelta_n\|_2^{1/2}\\
			&\le \sqrt{2\sigma}\, s^{3/4} \|\bXi_S\|^{1/2}\|\tilde\bDelta_n\|_2^{1/2}.
			\label{Z3}
	\end{align}
	Finally, the third term in the right-hand side of \eqref{Z1} can be bounded as follows:
	\begin{equation}
		\Big\| \sum_{i\in S}\bar\bxi_iw_i\Big\|_2 = \|\bXi_S \bsw\|_2\le \sqrt{s}\,\|\bXi_S\|.
		\label{Z4}
	\end{equation}
	Combining \eqref{Z1}, \eqref{Z2}, \eqref{Z3} and \eqref{Z4}, we arrive at
	\begin{align}
	\|\bL(\hat{\bTheta}-\bTheta) \|_2
		&\le 2\sigma\sum_{i\in S}\big(|\eta_i| + \big\{2\s|\tilde\bDelta_n^\top 
		\bar\bxi_i|\big\}^{1/2}\big) +1.96\,\sigma s\gamma
			+ {s}\big\|\tilde\bDelta_n\big\|_2  + \sigma\sqrt{s}\,\|\bXi_S\|\\
		&\le 2\sigma\sum_{i\in S}|\eta_i|+2.21\,\sigma s\g+\sqrt{2\sigma}\, s^{3/4} \|\bXi_S\|^{1/2}
		\big\|\tilde\bDelta_n\big\|_2^{1/2}+\sigma\sqrt{s}\,\|\bXi_S\|\\
		&\le 2\sigma\sum_{i\in S}|\eta_i| +2.34\,\sigma s\gamma + 
		2\sigma\sqrt{s}\,\|\bXi_S\|.\label{Z5}
	\end{align}			
	According to \citep[Corollary~5.35]{vershynin_2012} (recalled
	in~\Cref{lemma_Wishart1} below for the reader's convenience) the event
	$\O_3 = \big\{ \|\bXi_S\| \le \sqrt{s}+\sqrt{p}+\{2\log(8/\delta)\}^{1/2} \big\}$
  has probability at least $1-\delta/8$. One can also check that with probability
	at least $1-\delta/8$, the event $\Omega_4 = \{\sum_{i\in S}|\eta_i| \le s + 
	\sqrt{s\log(8/\delta)}\}$ is realized. Assuming that $\delta\le 1/2$ so that 
	$\log (8/\delta)\le (4/3)\log (4/\delta)$, this implies that in $\O_1\cap\bar\O$ 
	with $\bar\O=\O_2\cap\O_3\cap\Omega_4$, we have
	\begin{align}
		\|\bL(\hat{\bTheta}-\bTheta) \|_2				
		&\le 4\sigma(\,s\gamma+ s + \sqrt{sp} +  \{2s\log(4/\delta)\}^{1/2}).
	\end{align}
	This completes the proof.

We denote by $\bu_i\in\RR^n$ the column vector corresponding to the $i$-th row of $\bfU$.
    On the one hand, since $\nicefrac1n\bfJ_n$ is an orthogonal projection matrix, we have by the Pythagorean theorem
	\begin{align}
		\|\bfPi\bu^i\|_2^2 &= \|\bu^i\|_2^2 -\frac1{n^2} \|\bfJ_n\bu^i\|_2^2.
	\end{align}
    In particular, this implies that
	\begin{align}\label{ineq:1}
		\|\bfU\bfPi\|_F^2 &= \|\bfU\|_F^2 -\frac1{n^2} \|\bfU\bfJ_n\|_F^2.
	\end{align}
	On the other hand,
	\begin{align}
		\|\bfU\bfJ_n\|_F &= \|\mathbf \bfU 1_n\mathbf 1_n^\top\|_F =\sqrt{n}\, \|\bfU \mathbf 1_n^\top\|_2 = \sqrt{n}\, \Big\|\sum_{i=1}^n \bu_i\Big\|_2
        \le \sqrt{n}\, \sum_{i=1}^n \|\bu_i\|_2.
	\end{align}
    Using \eqref{cone_cond} and the Cauchy-Schwarz inequality, we get
	\begin{align}
		\sum_{i=1}^n \|\bu_i\|_2 &\le (1+a)\sum_{i\in S} \|\bu_i\|_2 \le (1+a)|S|^{1/2}\Big(\sum_{i\in S} \|\bu_i\|^2_2\Big)^{1/2} \le (1+a)|S|^{1/2}\|\bfU\|_F.
	\end{align}
    This readily yields $\|\bfU\bfJ_n\|_F \le (1+a) (n|S|)^{1/2}\|\bfU\|_F$. Combining this inequality with \eqref{ineq:1}, we get the claim of the lemma.

First assume that $x\ge 4d$. Combining the relation
	\begin{align}
		\esp\big(\eta\, \fcar_{\eta\ge d+x}\big) &= (d+x)\prob(\eta\ge d+x)+\int_x^\pinf \prob(\eta\ge d+t)\,dt
	\end{align}
	with Lemma~\ref{lemme_chideux}, we get
	\begin{align}
		\esp\big(\eta\, \fcar_{\eta\ge d+x}\big)
		&\le (d+x) e^{-x/4} + \int_x^\pinf e^{-t/4}\, dt\\
		&\le (4+d+x)e^{-x/4}\le (4d+x)e^{-x/4}\le 2xe^{-x/4}. \phantom{\int_0^\pinf}
	\end{align}
	Now assume that $x<4d$. Then, using the Cauchy-Schwarz inequality and
	Lemma~\ref{lemme_chideux},
	\begin{align}
	\esp\big(\eta\, \fcar_{\eta\ge d+x}\big) \le \sqrt{d(d+2)} e^{-x^2/32d}.
	\end{align}

It is clear that
	\begin{align}
	\esp[\|\bfA\|^2] &\le 3(N+n) + \int_0^\pinf \prob(\|\bfA\|^2>3(N+n)+x)\, dx \\
	&\le 3(N+n) + 12\,\int_0^\pinf te^{-t^2/2}\, dt.
	\end{align}
	The result follows from the fact that the last integral is equal to one.

