\setstretch{1.2}
\SetAlgoLined
\SetKwInOut{Input}{input}\SetKwInOut{Output}{output}
\Input{matrix $\bfY$ and noise variance $\s$, threshold $\l$.}
\Output{vector $\hat\bL{}^{\rm GSS}$.}
initialization $I \gets [n]$ and $\hat S \gets \varnothing$.\;
\Repeat{$I$ is empty or $\hat J$ is empty}{
Set $\calI \gets \big\{J\subseteq I : \|\bL(\bfY_{J})\|_2^2
\ge 12\sigma^2 (|J|p + \l |J|^2)\big\}$.\;
\eIf{$\calI =\varnothing$}{$\hat J\gets\varnothing$\;
}{
Set $\hat J \gets \text{arg}\min\big\{|J| : J\in\calI\big\}$.\;
}
Update $\hat S \gets \hat S \cup \hat J$.\;
Update $I \gets I\setminus \hat J$.\;
}
\Return{$\hat\bL{}^{\rm GSS}\gets \sum_{i\in\hat S} \bY_i$}
\caption{Greedy subset selection algorithm}
\label{algo:1}

\setstretch{1.2}
\SetAlgoLined
\SetKwInOut{Input}{input}\SetKwInOut{Output}{output}
\Input{matrix $\bfY$, noise variance $\sigma^2$ and confidence level $\d$.}
\Output{vector $\hat\bL{\!\!\!}^{\rm adGSS}$.}
Set ${\rm dist} \gets \sigma^{-1}\|\hat\bL{}^{\rm GSS}-\bL(\bfY)\|_2$.\;
Set $\l \gets \nicefrac32 \log(\nicefrac{4n}{\d})$.\;
Set
$\hat s \gets \min\Big\{k\in[n]: {\rm dist}\le \sqrt{60k(p+\l k)}+\sqrt{n(2p+3\log(2/\delta))}\Big\}$
(if the set is empty, set $\hat s \gets n$)\;
\eIf{$60\hat s(p+\l \hat s)\le 2np+3n\log(2/\delta)$}
{$\hat\bL{}^{\rm adGSS}\gets \hat\bL{}^{\rm GSS}$\;}
{$\hat\bL{}^{\rm adGSS}\gets \bL(\bfY)$\;}
\Return{$\hat\bL{}^{\rm adGSS}$}
\caption{Adaptive GSS}
\label{algo:2}

\setstretch{1.2}
\SetAlgoLined
\SetKwInOut{Input}{input}\SetKwInOut{Output}{output}\SetKwInOut{Parameter}{parameters}
\Input{matrix $\bfY$, noise variance $\s$, number of outliers $s$.}
\Parameter{number of iterations $N$, confidence level $\d$.}
\Output{vectors $\hat\bL_n{\!\!\!}^{\rm IST}$ and $\hat\bmu^{\rm IST}$.}
initialization\; 
\qquad $\hat\bTheta \gets $ solution of \eqref{definition_groupestimator} with 
$\lambda^2 = 32\sigma^2(p+8\log(n/\delta))$\;
\qquad $\epsilon\gets  \sqrt{288}\,\displaystyle\frac{s\lambda}{n\sigma}$\;
\For{$k=1,\ldots,N$}{
Set $\hat\bL_n \gets \bL_n(\hat\bTheta)$\;
Set $\gamma^2\gets 8\epsilon^2+4\sqrt{4\epsilon^4+p\epsilon^2}$\;
\For{$i=1,\ldots,n$}{
Set $\bZ_i \gets (\bfY\bfPi)_i+\hat\bL_n$\;
Set 
$\displaystyle
\btheta_i \gets \bZ_i\bigg(1-\frac{\sigma\gamma}{(\|\bZ_i\|_2^2-
\frac{n-1}{n}\sigma^2 p)^{1/2}_+}\bigg)_+.
$
}
{
update\;
\qquad $\hat\bTheta \gets [\hat\btheta_1,\ldots,\hat\btheta_n]$.\;
\qquad $\epsilon\gets \nicefrac{4}{n}(\,s\gamma+ s + \sqrt{sp} + 
\{2s\log(4/\delta)\}^{1/2})$\;
}
}
\Return{$\hat\bL{}^{\rm IST}_n\gets \bL_n(\hat\bTheta)$ and 
$\hat\bmu{}^{\rm IST}=\bL_n(\bfY)-\hat\bL{}^{\rm IST}_n$.} 
\caption{Iterative Soft Thresholding}
\label{algo:3}

