Note that none of the estimators discussed earlier in this work attain the
upper bound $\sigma^2(s^2\wedge np+sp)$; indeed, the latter is obtained as the
minimum of the risk of two estimators. Interestingly, one can design a single
estimator that attains this rate. Previous sections contain all the necessary
ingredients for this. We will illustrate the trick in the case of the GSS
estimator, but similar technique can be applied to any estimator for which an
``in deviation'' risk bound is established.

The idea is to combine the GSS estimator and the naive estimator
$\hat\bL=\bL(\bfY)$, with the aim of choosing the ``best'' one.
The combination can be performed using the Lepski method \citep{Lepski91},
also known as intersection of confidence intervals \citep{Golden}.
The method is described in \Cref{algo:2}. The construction is
based on the following two facts:
\begin{enumerate}
    \item The true value $\bL(\bTheta)$ lies with probability $1-\d/2$ in the
    ball $\mathcal B(\bL(\bfY);r_1)$ with $(r_1/\s)^2={2np+3n\log(2/\delta)}$.
    \item The true value $\bL(\bTheta)$ lies with probability $1-\d/2$ in the
    ball $\mathcal B(\hat\bL{}^{\rm GSS};r_2)$ with $(r_2/\s)^2=60s(p+\l s)$ (cf.\ \Cref{theorem_GSS}).
\end{enumerate}
These two facts imply that with probability at least $1-\d$ the balls
$\mathcal B(\bL(\bfY);r_1)$ and $\mathcal B(\hat\bL{}^{\rm GSS};r_2)$
have nonempty intersection. As a consequence, in this event, we have
$\|\bL(\bfY)-\hat\bL{}^{\rm GSS}\|_2 \le r_1+r_2$ and, therefore, $\hat s\le s$.
Now, if $60\hat s(p+\l \hat s)\le 2np+3n\log(2/\delta)$, then
$\hat\bL{}^{\rm adGSS}=\hat\bL{}^{\rm GSS}$ and we have
\begin{align}
    \|\hat\bL{}^{\rm adGSS}-\bL(\bTheta)\|_2 =  \|\hat\bL{}^{\rm GSS}-\bL(\bTheta)\|_2 \le r_2
\end{align}
along with
\begin{align}
    \|\hat\bL{}^{\rm adGSS}-\bL(\bTheta)\|_2
        &=  \|\hat\bL{}^{\rm GSS}-\bL(\bfY)\|_2 +\|\bL(\bfY)-\bL(\bTheta)\|_2\\
        &\le \{\sigma\sqrt{60\hat s(p+\l\hat s)}+ r_1\} +r_1\le 3r_1.
\end{align}
Thus, $\|\hat\bL{}^{\rm adGSS}-\bL(\bTheta)\|_2 \le 3 (r_1\wedge r_2)$. In the second case, $60\hat s(p+\l \hat s)\ge 2np+3n\log(2/\delta)$, we have
$\|\hat\bL{}^{\rm adGSS}-\bL(\bTheta)\|_2 =  \|\bL(\bfY)-\bL(\bTheta)\|_2 \le r_1=r_1\wedge r_2$, where the last equality follows from the fact that
$\hat s\le s$. Thus, we have established the following result.

This result, proved in \Cref{proofs_robust}, shows that the rate of the profiled 
penalized likelihood estimator of $\bmu$, with a group lasso penalty, converges at the
rate $\sigma^2\big(\frac{s^2p}{n^2}\vee \frac{p}{n}\big)$, which coincides with the one
obtained\footnote{To be precise, \citep{Gao2015} establish only a lower bound for
the element-wise median, but a matching upper bound can be proved as well.} by \citep{Gao2015}.
In the rest of this section, we will propose an estimator which improves on this rate. 
To this end, we start with obtaining a simplified expression for the group lasso
estimator $\hat\bTheta$.

First, using the fact that 
$\bfPi\boldsymbol{t}^j = \boldsymbol{t}^j - (\bfI_n-\bfPi)\boldsymbol{t}^j$, we get 
$\|\bfPi(\bY^j-\boldsymbol{t}^j) \|_2^2 = \|\bfPi\bY^j-\boldsymbol{t}^j \|_2^2 -
(\nicefrac1n) \big(\mathbf 1_n^\top\boldsymbol{t}^j\big)^2$, so that
\begin{equation}
	\hat{\bfT} \in \arg\min \Big\{ \sum_{i=1}^n \| (\bfY\bfPi)_i-\boldsymbol{t}_i \|_2^2 - \frac1n \Big\| \sum_{i=1}^n \boldsymbol{t}_i \Big\|_2^2 + \sum_{i=1}^n \l_i \|\boldsymbol{t}_i\|_2 \Big\}.
\end{equation}
Recall that $\bL_n(\bTheta) = (\nicefrac1n) \bL(\bTheta)$. The first-order necessary 
conditions imply that, for every $i$ such that $\hat{\bt}_i\neq\mathbf 0_p$,
\begin{equation}
	-2\big( (\bfY\bfPi)_i-\hat{\bt}_i \big) - 2 \bL_n(\hat{\bTheta}) + \frac{\l_i \hat{\bt}_i}{\|\hat{\bt}_i\|_2} =\mathbf  0_p.
\end{equation}
Furthermore, $\hat\bt_i=\mathbf 0_p$ if and only if
$\big\|2 (\bfY\bfPi)_i+ 2\bL_n(\hat{\bTheta}) \big\|_2\le \l_i$. 
We infer that
\begin{equation}
	\hat{\bt}_i = \frac{(\bfY\bfPi)_i+\bL_n(\hat{\bTheta}) }{\big\|(\bfY\bfPi)_i+
	\bL_n(\hat{\bTheta}) \big\|_2}~\Big( \big\|(\bfY\bfPi)_i+\bL_n(\hat\bTheta) \big\|_2 - \frac{\l_i}2 \Big)_+
\end{equation}
for every $i$. Finally, denoting $\bZ_i=(\bfY\bfPi)_i+\bL_n(\hat{\bTheta})$,  we get
\begin{equation}\label{equation_grouplasso}
	\hat{\bt}_i = \bZ_i \Big( 1-\frac{\l_i}{2\|\bZ_i \|_2} \Big)_+.
\end{equation}
This formula shows the clear analogy between the group lasso estimator $\hat\bTheta$ 
and the soft thresholding estimator studied in the previous section. This analogy
suggests to choose the tuning parameters in a data driven way; namely, it is tempting
to set 
\begin{align} \label{Z:0}
\l_i = \frac{2\gamma\sigma\|\bZ_i\|_2}{(\|\bZ_i\|_2^2-\sigma^2p)_+^{1/2}}
\qquad\Longrightarrow
\qquad
\hat{\bt}_i = \bZ_i \Bigg( 1-\frac{\gamma\sigma}{(\|\bZ_i\|_2^2-\sigma^2p)_+^{1/2}} \Bigg)_+.
\end{align}
Unfortunately, such a choice is impossible to realize since this $\l_i$ depends on the 
solution $\hat\bTheta$ of the optimization problem, which in turn is defined through $\l_i$. 
To circumvent this problem, we suggest to use an iterative algorithm that starts from
an initial estimator $\hat\bL_n$ of $\bL_n(\bTheta)$, defines the vectors 
$\bZ_i = (\bfY\bfPi)_i+\hat\bL_n$ and then updates $\hat\bL_n$ by the formula
$\hat\bL_n = \bL_n(\hat\bTheta)$, where the columns of the matrix $\hat\bTheta$ are 
defined by the second equality in \eqref{Z:0}. This algorithm, called iterative
soft thresholding, is described in \Cref{algo:3}. 
\begin{algorithm}[hbt]
\setstretch{1.2}
\SetAlgoLined
\SetKwInOut{Input}{input}\SetKwInOut{Output}{output}\SetKwInOut{Parameter}{parameters}
\Input{matrix $\bfY$, noise variance $\s$, number of outliers $s$.}
\Parameter{number of iterations $N$, confidence level $\d$.}
\Output{vectors $\hat\bL_n{\!\!\!}^{\rm IST}$ and $\hat\bmu^{\rm IST}$.}
initialization\; 
\qquad $\hat\bTheta \gets $ solution of \eqref{definition_groupestimator} with 
$\lambda^2 = 32\sigma^2(p+8\log(n/\delta))$\;
\qquad $\epsilon\gets  \sqrt{288}\,\displaystyle\frac{s\lambda}{n\sigma}$\;
\For{$k=1,\ldots,N$}{
Set $\hat\bL_n \gets \bL_n(\hat\bTheta)$\;
Set $\gamma^2\gets 8\epsilon^2+4\sqrt{4\epsilon^4+p\epsilon^2}$\;
\For{$i=1,\ldots,n$}{
Set $\bZ_i \gets (\bfY\bfPi)_i+\hat\bL_n$\;
Set 
$\displaystyle
\btheta_i \gets \bZ_i\bigg(1-\frac{\sigma\gamma}{(\|\bZ_i\|_2^2-
\frac{n-1}{n}\sigma^2 p)^{1/2}_+}\bigg)_+.
$
}
{
update\;
\qquad $\hat\bTheta \gets [\hat\btheta_1,\ldots,\hat\btheta_n]$.\;
\qquad $\epsilon\gets \nicefrac{4}{n}(\,s\gamma+ s + \sqrt{sp} + 
\{2s\log(4/\delta)\}^{1/2})$\;
}
}
\Return{$\hat\bL{}^{\rm IST}_n\gets \bL_n(\hat\bTheta)$ and 
$\hat\bmu{}^{\rm IST}=\bL_n(\bfY)-\hat\bL{}^{\rm IST}_n$.} 
\caption{Iterative Soft Thresholding}
\label{algo:3}
\end{algorithm}

Prior to stating the theorem that describes the statistical complexity of this estimator,
we present a result that explains why such an iterative algorithm succeeds in improving
the convergence rate.

It follows from this theorem that at each iteration of the algorithm 
we improve the precision of estimation of $\bL_n(\bTheta)$. Indeed, if $\epsilon_k$ 
is an upper bound on the error $\|\hat\bL_n\!{}^{(k)}-\bL_n(\bTheta)\|_2/\s$ at the $k$th 
iteration, then we get from the last theorem that
\begin{align}\label{eq:recursion}
\epsilon_{k+1} \le \frac{8s}{n}
\big(2\epsilon_k^2+(4\epsilon_k^4+p\epsilon_k^2)^{1/2}\big)^{1/2} +a,
\end{align}
with $a= (4/n)(s+\sqrt{sp}+\{2s\log(4/\delta)\}^{1/2})$.

\begin{proof}
	First assume that $x\ge 4d$. Combining the relation
	\begin{align}
		\esp\big(\eta\, \fcar_{\eta\ge d+x}\big) &= (d+x)\prob(\eta\ge d+x)+\int_x^\pinf \prob(\eta\ge d+t)\,dt
	\end{align}
	with Lemma~\ref{lemme_chideux}, we get
	\begin{align}
		\esp\big(\eta\, \fcar_{\eta\ge d+x}\big)
		&\le (d+x) e^{-x/4} + \int_x^\pinf e^{-t/4}\, dt\\
		&\le (4+d+x)e^{-x/4}\le (4d+x)e^{-x/4}\le 2xe^{-x/4}. \phantom{\int_0^\pinf}
	\end{align}
	Now assume that $x<4d$. Then, using the Cauchy-Schwarz inequality and
	Lemma~\ref{lemme_chideux},
	\begin{align}
	\esp\big(\eta\, \fcar_{\eta\ge d+x}\big) \le \sqrt{d(d+2)} e^{-x^2/32d}.
	\end{align}
\end{proof}

